const input = $input.first().json.body || $input.first().json;

const topic = input.topic;
const topicId = input.topic_id || `topic_${Date.now()}`;
const researchId = input.research_id;

if (!topic && !researchId) {
  throw new Error('Must provide topic or research_id');
}

const format = input.format || 'ebook';
const targetLength = input.target_length || 'medium';
const style = input.style || 'practical';
const callbackWorkflow = input.callback_workflow || null;

const validFormats = ['ebook', 'course', 'blog_series', 'lead_magnet'];
if (!validFormats.includes(format)) {
  throw new Error(`Invalid format: ${format}`);
}

const formatConfig = {
  ebook: { minSections: 8, maxSections: 14, wordsPerSection: { short: 800, medium: 1200, long: 2000 } },
  course: { minSections: 4, maxSections: 8, lessonsPerModule: { short: 3, medium: 5, long: 7 } },
  blog_series: { minSections: 5, maxSections: 10, wordsPerPost: { short: 800, medium: 1500, long: 2500 } },
  lead_magnet: { minSections: 3, maxSections: 5, wordsPerSection: { short: 400, medium: 600, long: 1000 } }
};

return [{
  json: {
    topic: topic,
    topic_id: topicId,
    research_id: researchId,
    format: format,
    target_length: targetLength,
    style: style,
    config: formatConfig[format],
    callback_workflow: callbackWorkflow,
    session_id: `outline_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    started_at: new Date().toISOString()
  }
}];

const config = $('Validate & Configure').first().json;
return [{
  json: {
    ...config,
    research: {
      summary: `Research on ${config.topic}`,
      key_themes: [],
      top_insights: [],
      quotes: [],
      statistics: []
    }
  }
}];

const config = $('Validate & Configure').first().json;
const tableData = $input.first().json;

let insights = [], quotes = [], statistics = [], sources = [], keyThemes = [];
try { insights = JSON.parse(tableData.insights || '[]'); } catch(e) {}
try { quotes = JSON.parse(tableData.quotes || '[]'); } catch(e) {}
try { statistics = JSON.parse(tableData.statistics || '[]'); } catch(e) {}
try { sources = JSON.parse(tableData.sources || '[]'); } catch(e) {}
try { keyThemes = JSON.parse(tableData.key_themes || '[]'); } catch(e) {}

const research = {
  summary: tableData.summary || '',
  quality_score: tableData.quality_score || 70,
