const inputData = $('Select Best Title').first().json;
const outlineRaw = $input.first().json.message?.content || '{}';

let outlineData = { outline: { sections: [] } };
try { outlineData = JSON.parse(outlineRaw); } catch (e) {}

const outline = outlineData.outline || {};
const sections = (outline.sections || []).map((s, i) => ({
  ...s,
  number: s.number || i + 1,
  status: 'pending',
  target_words: s.target_words || 1000
}));

const totalWords = sections.reduce((sum, s) => sum + (s.target_words || 0), 0);
let qualityScore = 70;
if (sections.length >= inputData.config.minSections) qualityScore += 15;
if (sections.every(s => s.key_points?.length >= 2)) qualityScore += 10;
qualityScore = Math.min(100, qualityScore);

const completedAt = new Date().toISOString();
const durationMs = new Date(completedAt) - new Date(inputData.started_at);

const outlineId = `outline_${inputData.session_id}`;

// Build Markdown document
let markdown = `# ${outline.title || inputData.selected_title}\n\n`;
if (outline.subtitle || inputData.selected_subtitle) {
  markdown += `### ${outline.subtitle || inputData.selected_subtitle}\n\n`;
}
markdown += `**Outline ID:** ${outlineId}\n`;
markdown += `**Format:** ${inputData.format}\n`;
markdown += `**Sections:** ${sections.length}\n`;
markdown += `**Target Words:** ${totalWords.toLocaleString()}\n`;
markdown += `**Quality Score:** ${qualityScore}/100\n`;
markdown += `**Generated:** ${completedAt}\n\n`;
markdown += `---\n\n`;

markdown += `## Table of Contents\n\n`;
sections.forEach(s => {
  markdown += `${s.number}. ${s.title}\n`;
});
markdown += `\n---\n\n`;

markdown += `## Detailed Outline\n\n`;
sections.forEach(section => {
  markdown += `### ${section.number}. ${section.title}\n\n`;
  markdown += `**Type:** ${section.type}\n`;
  markdown += `**Target Words:** ${section.target_words}\n\n`;
  if (section.description) {
    markdown += `${section.description}\n\n`;
  }
  if (section.key_points?.length) {
    markdown += `**Key Points:**\n`;
    section.key_points.forEach(point => {
      markdown += `- ${point}\n`;
    });
    markdown += `\n`;
  }
  markdown += `---\n\n`;
});

markdown += `*Generated by Production Line W6 Outline Generator*\n`;

// Create safe filename
const safeTitle = (outline.title || inputData.topic)
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 40);
const timestamp = new Date().toISOString().split('T')[0];
const fileName = `${safeTitle}_outline_${timestamp}.md`;
const filePath = `C:/dev/production_line/outlines/${fileName}`;

const outlinePackage = {
  outline_id: outlineId,
  research_id: inputData.research_record_id || inputData.research_id,
  topic: inputData.topic,
  topic_id: inputData.topic_id,
  title: outline.title || inputData.selected_title,
  subtitle: outline.subtitle || inputData.selected_subtitle,
  format: inputData.format,
  style: inputData.style,
  section_count: sections.length,
  total_target_words: totalWords,
  sections: JSON.stringify(sections),
  all_titles: JSON.stringify(inputData.all_titles || []),
  quality_score: qualityScore,
  file_path: filePath,
  markdown_content: markdown,
  callback_workflow: inputData.callback_workflow,
  started_at: inputData.started_at,
  completed_at: completedAt,
  duration_seconds: Math.round(durationMs / 1000),
  status: 'ready'
};

return [{ json: outlinePackage }];

const data = $('Build Outline Package').first().json;
const content = data.markdown_content;

const binaryData = Buffer.from(content, 'utf-8');

return [{
  json: {
    file_path: data.file_path
  },
  binary: {
    data: {
      data: binaryData.toString('base64'),
      mimeType: 'text/markdown',
      fileName: data.file_path.split('/').pop()
    }
  }
}];

